import{_ as t,o as i,c as a,a0 as o}from"./chunks/framework.ChlVJx0I.js";const g=JSON.parse('{"title":"skill-migrate runs sequential migrations with a committed changelog","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0032-skill-migrate-runs-sequential-migrations-with-a-committed-changelog.md","filePath":"adr/0032-skill-migrate-runs-sequential-migrations-with-a-committed-changelog.md","lastUpdated":1791297629000}'),r={name:"adr/0032-skill-migrate-runs-sequential-migrations-with-a-committed-changelog.md"};function n(s,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-migrate-runs-sequential-migrations-with-a-committed-changelog" tabindex="-1">skill-migrate runs sequential migrations with a committed changelog <a class="header-anchor" href="#skill-migrate-runs-sequential-migrations-with-a-committed-changelog" aria-label="Permalink to &quot;skill-migrate runs sequential migrations with a committed changelog&quot;">​</a></h1><p>The upstream skills renamed the domain docs layout (<code>CONTEXT.md</code> to <code>GLOSSARY.md</code>, <code>CONTEXT-MAP.md</code> to <code>GLOSSARY-MAP.md</code>, <code>CONTEXT-FORMAT.md</code> to <code>GLOSSARY-FORMAT.md</code>), so every underlying repo that still ships the old layout disagrees with what the skills expect. Editing the repos by hand would leave no trace of which structure version each carries, and the next structural change would start the same chore over. We decided: a deterministic extension, skill-migrate, owns the migrations. Each Target repo carries a committed, append-only Migration changelog under <code>.pi/</code>. The runner applies named, numbered migrations in strict order (void to 1, 1 to 2, ...), checks preconditions before and postconditions after each, and records the version, the migration name, the pi-extensions commit that applied it, and the UTC date time for every step.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>A one-off, LLM-driven pass per repo.</strong> Rejected because it is not replayable across repos, leaves no auditable record of a repo&#39;s structure version, and hands the same judgment call to a model on every run.</li><li><strong>Self-migration: the extension notices a stale repo and migrates it on its own.</strong> Rejected because the operator drives structure changes at will, and a silent structural rewrite of the working tree is not what an agent does unprompted. The extension exposes exactly two verbs: status and migrate.</li><li><strong>Per-migration backups with in-tool rollback.</strong> Rejected because every target repo is git. A failed migration appends nothing to the changelog and points the operator at <code>git restore</code> plus a re-run, which keeps the engine small and deterministic. Precondition checks make the re-run safe: a migration refuses to start unless the tree is in the state it expects.</li><li><strong>A top-level current version in the changelog file.</strong> Rejected because it duplicates the last record, and two copies of one version drift.</li><li><strong>Rewrite references to the format file without renaming the file.</strong> Rejected because the reference rewrite would then point at a file that no longer exists: the upstream rename covers <code>CONTEXT-FORMAT.md</code>, so the root format file is renamed like the glossary and the map, and the old and new names present together is ambiguous state like any other root pair.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Once a repo carries a changelog, its shape is fixed: an append-only migrations array, four fields per record, and the pi-extensions commit as the extension identity. Changing the format later is itself a migration.</li><li>A failed migration can leave the tree partly changed with the changelog untouched. That is deliberate: the audit file records only completed steps, and git is the rollback layer.</li><li>A repo that never had the old files still passes the glossary rename, because the renames are conditional on presence and the reference rewrite runs either way.</li><li>Migrations are defined once in the extension and applied to many repos. A new structural expectation is one new numbered step; the runner never changes.</li><li>The extension identity is anchored to the checkout&#39;s own git toplevel: the commit SHA is recorded only when the checkout is the toplevel. A package installed inside a consumer git repo records its package version, not the consumer&#39;s SHA.</li><li>A repo whose changelog is ahead of the registry is up to date: it has no pending migration. <code>status</code> and <code>migrate</code> report its actual version and change nothing.</li><li>Files that document the rename itself (this ADR, the glossary terms) carry the old names as historical data. The rewrite cannot tell a reference from history; where a rewrite touched such a file, the historical wording was repaired by hand.</li></ul>',6)])])}const u=t(r,[["render",n]]);export{g as __pageData,u as default};
